/**
 * Schema of the centralised changelog JSON, `global.json` schema version 2 (ADR 0040), as
 * generated by `scripts/generate_global_json.py` of DyingStar-game/changelog (its ADR 0001).
 */
import { z } from 'zod'

/** A label per language. */
const labelsSchema = z.object({ en: z.string(), fr: z.string() })

/** One changelog bullet. */
export const changelogItemSchema = z.object({
  /** Keep a Changelog type key (`added`, `fixed`…), null for entries written before types. */
  type: z.string().nullable(),
  /** Area key of the component (`vehicles`, `ui`…), null for entries written before areas. */
  area: z.string().nullable(),
  /** Markdown, one display line per `\n`: the bullet, then its sub-lines. */
  text: z.string()
})

const localeEntriesSchema = z.object({
  en: z.array(changelogItemSchema),
  fr: z.array(changelogItemSchema)
})

const releaseSchema = z.object({
  version: z.string(),
  date: z.string(),
  yanked: z.boolean(),
  /** GitHub compare page of the version, null when the component does not tag releases. */
  url: z.string().nullable(),
  entries: localeEntriesSchema
})

const componentSchema = z.object({
  repo: z.string(),
  /** Areas in display order. */
  areas: z.record(z.string(), labelsSchema),
  unreleased: z.object({ url: z.string().nullable(), entries: localeEntriesSchema }),
  /** Newest first. */
  releases: z.array(releaseSchema)
})

export const globalChangelogSchema = z.object({
  schema_version: z.literal(2),
  generated_at: z.string(),
  /** Types in display order. */
  types: z.record(z.string(), labelsSchema),
  components: z.record(z.string(), componentSchema)
})
